const aruzSortedPhrases = {
  "en": Object.entries(aruzPhrases.en).sort((a, b) => b[0].length - a[0].length),
  "fr": Object.entries(aruzPhrases.fr).sort((a, b) => b[0].length - a[0].length)
};

class AruzI18nEngine {
  constructor() {
    this.supportedLangs = ['es', 'en', 'fr'];
    this.defaultLang = 'es';
    this.currentLang = this.detectLanguage();
    this.isTranslating = false;
    this._hasSnapshotted = false;
    this.init();
  }

  detectLanguage() {
    const urlParams = new URLSearchParams(window.location.search);
    const urlLang = urlParams.get('lang')?.toLowerCase();
    if (urlLang && this.supportedLangs.includes(urlLang)) {
      localStorage.setItem('aruz_lang', urlLang);
      return urlLang;
    }

    const savedLang = localStorage.getItem('aruz_lang')?.toLowerCase();
    if (savedLang && this.supportedLangs.includes(savedLang)) {
      return savedLang;
    }

    const browserLangs = navigator.languages || [navigator.language || 'es'];
    for (const bLang of browserLangs) {
      const short = bLang.substring(0, 2).toLowerCase();
      if (short === 'fr') return 'fr';
      if (short === 'en') return 'en';
      if (short === 'es') return 'es';
    }

    return this.defaultLang;
  }

  snapshotPristineDOM() {
    if (this._hasSnapshotted) return;
    this._hasSnapshotted = true;

    // 1. Snapshot data-i18n elements
    document.querySelectorAll('[data-i18n]').forEach(el => {
      if (el._origText === undefined) el._origText = el.textContent;
    });

    // 2. Snapshot form placeholders & options
    document.querySelectorAll('input, textarea').forEach(el => {
      if (el.placeholder && el._origPlaceholder === undefined) {
        el._origPlaceholder = el.placeholder;
      }
    });

    document.querySelectorAll('select option').forEach(opt => {
      if (opt._origText === undefined) opt._origText = opt.textContent;
    });

    // 3. Snapshot headings, paragraphs, buttons, labels
    document.querySelectorAll('h1, h2, h3, h4, h5, h6, p, a, button, span, li, label, th, td').forEach(el => {
      if (el.classList.contains('material-symbols-outlined') || el.classList.contains('lang-btn') || el.closest('.aruz-lang-switcher') || el.closest('#aruz-intro-overlay')) {
        return;
      }
      if (el._origHTML === undefined) {
        el._origHTML = el.innerHTML;
        el._origText = el.textContent;
      }
    });

    // 4. Snapshot TreeWalker text nodes
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (!node.nodeValue || !node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
        const parent = node.parentElement;
        if (!parent) return NodeFilter.FILTER_REJECT;
        const tag = parent.tagName.toLowerCase();
        if (tag === 'script' || tag === 'style' || tag === 'svg' || tag === 'path' || tag === 'noscript') return NodeFilter.FILTER_REJECT;
        if (parent.classList.contains('material-symbols-outlined') || parent.classList.contains('notranslate') || parent.classList.contains('lang-btn') || parent.closest('#aruz-intro-overlay') || parent.closest('.aruz-lang-switcher')) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });

    let node;
    while ((node = walker.nextNode())) {
      if (node._origText === undefined) {
        node._origText = node.nodeValue;
      }
    }
  }

  init() {
    this.renderLanguageSwitchers();
    this.snapshotPristineDOM();
    if (this.currentLang !== 'es') {
      this.applyLanguage(this.currentLang);
    } else {
      this.restoreSpanishDOM();
    }
  }

  setLanguage(lang) {
    if (!this.supportedLangs.includes(lang)) return;
    this.currentLang = lang;
    localStorage.setItem('aruz_lang', lang);
    if (lang === 'es') {
      this.restoreSpanishDOM();
    } else {
      this.applyLanguage(lang);
    }
    this.updateSwitcherUI();
  }

  applyLanguage(lang) {
    if (this.isTranslating) return;
    this.isTranslating = true;
    this.snapshotPristineDOM();
    document.documentElement.setAttribute('lang', lang);

    if (lang === 'es') {
      this.restoreSpanishDOM();
      this.isTranslating = false;
      return;
    }

    const dict = aruzPhrases[lang] || {};
    const dataKeys = aruzDataKeys[lang] || {};
    const sortedList = aruzSortedPhrases[lang] || [];

    // 1. Translate elements with data-i18n attributes (Header links, specs, badges, buttons)
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (dataKeys[key]) {
        el.textContent = dataKeys[key];
      }
    });

    // 2. Translate form placeholders and select options
    document.querySelectorAll('input, textarea').forEach(el => {
      if (el.placeholder) {
        const clean = (el._origPlaceholder || el.placeholder).trim();
        if (dict[clean]) {
          el.placeholder = dict[clean];
        }
      }
    });

    document.querySelectorAll('select option').forEach(opt => {
      const clean = (opt._origText || opt.textContent).trim();
      if (dict[clean]) {
        opt.textContent = dict[clean];
      }
    });

    // 3. Direct Element-level translation for full headings, paragraphs, spans & buttons
    document.querySelectorAll('h1, h2, h3, h4, h5, h6, p, a, button, span, li, label, th, td').forEach(el => {
      if (el.hasAttribute('data-i18n')) return; // handled strictly by step 1
      if (el.classList.contains('material-symbols-outlined') || el.classList.contains('lang-btn') || el.closest('.aruz-lang-switcher') || el.closest('#aruz-intro-overlay')) {
        return;
      }

      const origText = el._origText || el.textContent;
      const cleanText = origText.trim().replace(/\s+/g, ' ');
      const origHTML = el._origHTML || el.innerHTML;

      if (dict[cleanText] && !el.querySelector('div, section, article, nav, header, footer')) {
        if (origHTML.includes('<') && !origHTML.includes('<div')) {
          let translatedHTML = origHTML;
          for (let i = 0; i < sortedList.length; i++) {
            const es = sortedList[i][0];
            const target = sortedList[i][1];
            if (es.length > 2 && translatedHTML.includes(es)) {
              translatedHTML = translatedHTML.split(es).join(target);
            }
          }
          el.innerHTML = translatedHTML;
        } else {
          el.textContent = dict[cleanText];
        }
      }
    });

    // 4. Universal Live DOM TreeWalker for granular text nodes
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (!node.nodeValue || !node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
        const parent = node.parentElement;
        if (!parent) return NodeFilter.FILTER_REJECT;
        const tag = parent.tagName.toLowerCase();
        if (tag === 'script' || tag === 'style' || tag === 'svg' || tag === 'path' || tag === 'noscript') return NodeFilter.FILTER_REJECT;
        if (parent.hasAttribute('data-i18n') || parent.closest('[data-i18n]')) return NodeFilter.FILTER_REJECT;
        if (parent.classList.contains('material-symbols-outlined') || parent.classList.contains('notranslate') || parent.classList.contains('lang-btn') || parent.closest('#aruz-intro-overlay') || parent.closest('.aruz-lang-switcher')) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });

    let node;
    while ((node = walker.nextNode())) {
      const raw = node._origText || node.nodeValue;
      const clean = raw.trim().replace(/\s+/g, ' ');
      
      if (dict[clean]) {
        const match = raw.match(/^(\s*)(.*?)(\s*)$/s);
        if (match) {
          node.nodeValue = match[1] + dict[clean] + match[3];
        } else {
          node.nodeValue = dict[clean];
        }
      } else {
        let current = raw;
        let changed = false;
        for (let i = 0; i < sortedList.length; i++) {
          const esPhrase = sortedList[i][0];
          const targetPhrase = sortedList[i][1];
          if (esPhrase.length > 2 && current.includes(esPhrase)) {
            current = current.split(esPhrase).join(targetPhrase);
            changed = true;
          }
        }
        if (changed) {
          node.nodeValue = current;
        }
      }
    }

    this.isTranslating = false;
    window.dispatchEvent(new CustomEvent('aruzLanguageChanged', { detail: { lang } }));
  }

  restoreSpanishDOM() {
    this.snapshotPristineDOM();
    document.documentElement.setAttribute('lang', 'es');
    const esKeys = aruzDataKeys['es'] || {};

    // 1. Explicitly restore data-i18n elements using the canonical Spanish dictionary
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (esKeys[key]) {
        el.textContent = esKeys[key];
      } else if (el._origText !== undefined) {
        el.textContent = el._origText;
      }
    });

    // 2. Restore placeholders and select options
    document.querySelectorAll('input, textarea').forEach(el => {
      if (el._origPlaceholder !== undefined) {
        el.placeholder = el._origPlaceholder;
      }
    });

    document.querySelectorAll('select option').forEach(opt => {
      if (opt._origText !== undefined) {
        opt.textContent = opt._origText;
      }
    });

    // 3. Restore elements with stored _origHTML
    document.querySelectorAll('h1, h2, h3, h4, h5, h6, p, a, button, span, li, label, th, td').forEach(el => {
      if (el.hasAttribute('data-i18n')) return;
      if (el._origHTML !== undefined) {
        el.innerHTML = el._origHTML;
      }
    });

    // 4. Restore TreeWalker text nodes
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (!node.nodeValue || !node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
        const parent = node.parentElement;
        if (!parent) return NodeFilter.FILTER_REJECT;
        const tag = parent.tagName.toLowerCase();
        if (tag === 'script' || tag === 'style' || tag === 'svg' || tag === 'path' || tag === 'noscript') return NodeFilter.FILTER_REJECT;
        if (parent.hasAttribute('data-i18n') || parent.closest('[data-i18n]')) return NodeFilter.FILTER_REJECT;
        if (parent.classList.contains('material-symbols-outlined') || parent.classList.contains('notranslate') || parent.classList.contains('lang-btn') || parent.closest('#aruz-intro-overlay') || parent.closest('.aruz-lang-switcher')) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });

    let node;
    while ((node = walker.nextNode())) {
      if (node._origText !== undefined) {
        node.nodeValue = node._origText;
      }
    }

    this.isTranslating = false;
    window.dispatchEvent(new CustomEvent('aruzLanguageChanged', { detail: { lang: 'es' } }));
  }

  renderLanguageSwitchers() {
    const switcherHTML = `
      <div class="aruz-lang-switcher inline-flex items-center bg-black/70 border border-dorado-aruz/40 rounded-full px-2.5 py-1 text-[11px] font-sans font-bold tracking-wider backdrop-blur-md shadow-sm">
        <button type="button" onclick="window.AruzI18nInstance.setLanguage('es')" class="lang-btn px-2.5 py-0.5 rounded-full transition-all ${this.currentLang === 'es' ? 'bg-dorado-aruz text-carbon-aruz font-extrabold shadow-sm scale-105' : 'text-white/75 hover:text-dorado-aruz'}" data-lang="es">ES</button>
        <span class="text-white/25 mx-1">·</span>
        <button type="button" onclick="window.AruzI18nInstance.setLanguage('en')" class="lang-btn px-2.5 py-0.5 rounded-full transition-all ${this.currentLang === 'en' ? 'bg-dorado-aruz text-carbon-aruz font-extrabold shadow-sm scale-105' : 'text-white/75 hover:text-dorado-aruz'}" data-lang="en">EN</button>
        <span class="text-white/25 mx-1">·</span>
        <button type="button" onclick="window.AruzI18nInstance.setLanguage('fr')" class="lang-btn px-2.5 py-0.5 rounded-full transition-all ${this.currentLang === 'fr' ? 'bg-dorado-aruz text-carbon-aruz font-extrabold shadow-sm scale-105' : 'text-white/75 hover:text-dorado-aruz'}" data-lang="fr">FR</button>
      </div>
    `;

    document.querySelectorAll('.header-lang-slot').forEach(slot => {
      slot.innerHTML = switcherHTML;
    });
  }

  updateSwitcherUI() {
    document.querySelectorAll('.aruz-lang-switcher').forEach(switcher => {
      switcher.querySelectorAll('.lang-btn').forEach(btn => {
        const btnLang = btn.getAttribute('data-lang');
        if (btnLang === this.currentLang) {
          btn.className = 'lang-btn px-2.5 py-0.5 rounded-full transition-all bg-dorado-aruz text-carbon-aruz font-extrabold shadow-sm scale-105';
        } else {
          btn.className = 'lang-btn px-2.5 py-0.5 rounded-full transition-all text-white/75 hover:text-dorado-aruz';
        }
      });
    });
  }
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    window.AruzI18nInstance = new AruzI18nEngine();
  });
} else {
  window.AruzI18nInstance = new AruzI18nEngine();
}
